parameters.jsCode:
// Extract standardized error details
const execution = $execution || {};
const workflow = $workflow || {};
const error = $json.execution?.error || $json.error || {};

const errorPayload = {
  severity: 'HIGH',
  pipeline: 'common-law.ai Automation',
  workflowId: workflow.id || 'unknown',
  workflowName: workflow.name || 'unknown',
  executionId: execution.id || 'unknown',
  timestamp: new Date().toISOString(),
  errorMessage: error.message || 'An unknown error occurred during workflow execution',
  errorDescription: error.description || '',
  failedNode: error.node?.name || 'Unknown Node',
  executionUrl: execution.url || ''
};

return [{
  json: errorPayload
}];

